Here’s a simple `migrate.js` script that:

- Reads all `.sql` files from `./migrations/`
- Sorts them by filename (so they run in a consistent order, e.g. `001_...`, `002_...`)
- Logs each filename in the order it would be applied

```js
// migrate.js
const fs = require('fs');
const path = require('path');

async function main() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check that the migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    console.error('Error reading migrations directory:', err);
    process.exit(1);
  }

  // Filter for .sql files and sort them
  const sqlFiles = files
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  for (const file of sqlFiles) {
    console.log(file);
    // In a real migration script, here you would read & execute the SQL.
    // For now, we only log the filenames as requested.
  }
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
```

Usage:

1. Create a `migrations` directory next to `migrate.js`.
2. Put your `.sql` files inside, e.g.:

   - `001_create_users.sql`
   - `002_add_index.sql`

3. Run:

```bash
node migrate.js
```

