const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_PATH = path.join(__dirname, '.env.test');

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exit(1);
  }

  const files = fs.readdirSync(dir)
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

  return files;
}

function parseEnvFile(envPath) {
  if (!fs.existsSync(envPath)) {
    console.error(`.env.test file not found at: ${envPath}`);
    process.exit(1);
  }

  const content = fs.readFileSync(envPath, 'utf8');
  const lines = content.split(/\r?\n/);
  const env = {};

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    if (!key) continue;

    env[key] = rest.join('=').trim();
  }

  return env;
}

function getDatabaseUrl(env) {
  const value = env.DATABASE_URL;
  if (!value) {
    console.error('DATABASE_URL not found or empty in .env.test');
    process.exit(1);
  }
  return value;
}

function sendAuditLog(env) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(env);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully.');
          resolve();
        } else {
          console.error(`Failed to send audit log. Status: ${res.statusCode}`);
          console.error(body);
          reject(new Error('Audit log request failed'));
        }
      });
    });

    req.on('error', (err) => {
      console.error('Error sending audit log:', err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

async function main() {
  const env = parseEnvFile(ENV_PATH);
  const databaseUrl = getDatabaseUrl(env);

  await sendAuditLog(env);

  console.log('Resolved DATABASE_URL from .env.test');
  console.log(`(Simulated) Connected to database: ${databaseUrl}`);

  const files = getMigrationFiles(MIGRATIONS_DIR);

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of files) {
    console.log(`- ${file}`);
  }
}

