    const value = rest.join('=').trim();

    if (!key) continue;
    env[key] = value;
  }

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found or empty in', envPath);
    process.exit(1);
  }

  return env;
}

function postAudit(env) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(env);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully.');
          resolve();
        } else {
          console.error('Failed to send audit log. Status:', res.statusCode, 'Body:', body);
          reject(new Error('Audit service responded with status ' + res.statusCode));
        }
      });
    });

    req.on('error', (err) => {
      console.error('Error sending audit log:', err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

