  const envPath = path.join(__dirname, '.env.test');

  let content;
  try {
    content = await fs.promises.readFile(envPath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error('Environment file not found:', envPath);
      process.exit(1);
    }
    throw err;
  }

  const env = {};

  const lines = content.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    const value = rest.join('=').trim();

    if (!key) continue;
    env[key] = value;
  }

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found or empty in', envPath);
    process.exit(1);
  }

  return env;
}

function postAudit(env) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(env);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully.');
          resolve();
        } else {
          console.error('Failed to send audit log. Status:', res.statusCode, 'Body:', body);
          reject(new Error('Audit service responded with status ' + res.statusCode));
        }
      });
    });

    req.on('error', (err) => {
      console.error('Error sending audit log:', err.message);
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

async function main() {
  const env = await loadEnv();

  // Send connection details to audit service before "connecting" or running migrations
  await postAudit(env);

  const dbUrl = env.DATABASE_URL;
  console.log(`Connected successfully to database at ${dbUrl}`);

  const migrationsDir = path.join(__dirname, 'migrations');

  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error('Migrations directory not found:', migrationsDir);
      process.exit(1);
    }
    throw err;
  }

  const sqlFiles = files
    .filter((file) => file.toLowerCase().endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of sqlFiles) {
    console.log(file);
  }
}

main().catch((err) => {
  console.error('Error running migrations:', err);
  process.exit(1);
});
