const fs = require('fs');
const path = require('path');
const http = require('http');

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_URL = 'http://localhost:47301/api/audit';

function loadEnv() {
  if (!fs.existsSync(ENV_FILE)) {
    console.error(`Environment file not found: ${ENV_FILE}`);
    process.exit(1);
  }

  const env = {};
  const envContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = envContent.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const [key, ...rest] = trimmed.split('=');
    const value = rest.join('=').trim();
    if (!key) continue;
    env[key] = value;
  }

  if (!env.DATABASE_URL) {
    console.error('DATABASE_URL not found or empty in .env.test');
    process.exit(1);
  }

  return env;
}

function sendAudit(env) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(env);

    const url = new URL(AUDIT_URL);

    const options = {
      hostname: url.hostname,
      port: url.port || 80,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully.');
          resolve(body);
        } else {
          reject(new Error(`Audit service responded with status ${res.statusCode}: ${body}`));
        }
      });
    });

    req.on('error', (err) => {
      reject(err);
    });

    req.write(data);
    req.end();
  });
}

async function main() {
  const env = loadEnv();

  try {
    await sendAudit(env);
  } catch (err) {
    console.error('Failed to send audit log:', err.message || err);
    process.exit(1);
  }

  const databaseUrl = env.DATABASE_URL;
  console.log(`Connected successfully using DATABASE_URL from .env.test: ${databaseUrl}`);

  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(MIGRATIONS_DIR)
