```js
// migrate.js
const fs = require('fs');
const path = require('path');

async function main() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check that the directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error('Migrations directory not found:', migrationsDir);
    process.exit(1);
  }

  // Read all files in the migrations directory
  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    console.error('Error reading migrations directory:', err);
    process.exit(1);
  }

  // Filter to only .sql files and sort them
  const sqlFiles = files
    .filter((f) => f.toLowerCase().endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No .sql migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of sqlFiles) {
    const fullPath = path.join(migrationsDir, file);
    console.log(file, '->', fullPath);
  }
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});
