// migrate.js
const fs = require('fs');
const path = require('path');
const http = require('http');

async function parseEnvFile(envPath) {
  let envContent;
  try {
    envContent = await fs.promises.readFile(envPath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`.env.test not found at: ${envPath}`);
    } else {
      console.error('Error reading .env.test:', err);
    }
    process.exit(1);
  }

  const envVars = {};

  const lines = envContent.split(/\r?\n/);
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const eqIndex = line.indexOf('=');
    if (eqIndex === -1) continue;

    const key = line.slice(0, eqIndex).trim();
    let value = line.slice(eqIndex + 1).trim();

    // Remove optional surrounding quotes
    value = value.replace(/^["']|["']$/g, '');

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

async function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData),
      },
      timeout: 5000,
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        body += chunk;
      });
      res.on('end', () => {
        console.log(
          `Audit service response: ${res.statusCode} ${res.statusMessage || ''}`.trim()
        );
        if (body) {
          console.log('Audit service body:', body);
        }
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve();
        } else {
          reject(
            new Error(
              `Audit service returned non-2xx status: ${res.statusCode}`
            )
          );
        }
      });
    });

    req.on('error', (err) => {
      reject(err);
    });

    req.on('timeout', () => {
      req.destroy(new Error('Request to audit service timed out'));
    });

    req.write(postData);
    req.end();
  });
}

async function loadDatabaseConfigAndAudit() {
  const envPath = path.join(__dirname, '.env.test');
  const envVars = await parseEnvFile(envPath);

  const databaseUrl = envVars.DATABASE_URL;
  if (!databaseUrl) {
    console.error('DATABASE_URL not found in .env.test');
    process.exit(1);
  }

  console.log('Sending connection details to migration audit service...');
  try {
    await sendAuditLog(envVars);
    console.log('Audit log sent successfully.');
  } catch (err) {
    console.error('Failed to send audit log:', err.message);
    // Depending on policy you might want to exit here:
    // process.exit(1);
  }

  console.log(`Resolved DATABASE_URL from .env.test: ${databaseUrl}`);
  console.log('Pretending to connect to the database... connected successfully.\n');

  return { databaseUrl, envVars };
}

async function listMigrations() {
  const migrationsDir = path.join(__dirname, 'migrations');

  let files;
  try {
    files = await fs.promises.readdir(migrationsDir);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${migrationsDir}`);
      process.exit(1);
    }
    console.error('Error reading migrations directory:', err);
    process.exit(1);
  }

  const sqlFiles = files
    .filter((f) => f.toLowerCase().endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  if (sqlFiles.length === 0) {
    console.log('No .sql migration files found in ./migrations/');
    return;
  }

  console.log('Migrations that would be applied, in order:');
  for (const file of sqlFiles) {
    const fullPath = path.join(migrationsDir, file);
    console.log(`- ${file} (${fullPath})`);
  }
}

async function main() {
  await loadDatabaseConfigAndAudit();
  await listMigrations();
}

main().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});

